input.sparql:
SELECT ?zone ?zoneName ?tempSensor WHERE {
  ?ahu rdf:type brick:AirHandler ;
        rdfs:label "AHU03" .
  ?ahu brick:serves ?zone .
  ?zone rdfs:label ?zoneName .
  ?tempSensor brick:isPointOf ?zone ;
              rdf:type brick:Air_Temperature_Sensor .
}

SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER(CONTAINS(?label, "AHU03"))
}

SELECT ?ahu ?label WHERE {
  ?ahu rdf:type brick:AirHandler .
  ?ahu rdfs:label ?label .
}

SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(CONTAINS(STR(?s), "AHU03") || CONTAINS(STR(?o), "AHU03"))
}

SELECT ?zone ?zoneLabel WHERE {
  ?ahu rdfs:label "AHU03" .
  ?ahu brick:serves ?zone .
  ?zone rdfs:label ?zoneLabel .
}

SELECT ?zone ?zoneLabel ?tempSensor WHERE {
  BIND(<http://buildgraph.org/BG_large_office_2004_0000#AHU03> AS ?ahu)
  { ?ahu brick:serves ?zone } UNION { ?ahu brick:feeds ?vav . ?vav brick:serves ?zone }
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  OPTIONAL { ?tempSensor brick:isPointOf ?zone ; rdf:type brick:Air_Temperature_Sensor }
}

SELECT ?vav ?zone ?zoneLabel ?sensor WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU03> brick:feeds ?vav .
  ?vav brick:serves ?zone .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  OPTIONAL { ?sensor brick:isPointOf ?zone ; rdf:type brick:Air_Temperature_Sensor }
}

SELECT ?zone ?zoneLabel ?sensor WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#VAV_F4_Z05> brick:serves ?zone .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  OPTIONAL { ?sensor brick:isPointOf ?zone ; rdf:type brick:Air_Temperature_Sensor }
}

SELECT ?vav ?zone ?zoneLabel ?sensor ?sensorLabel WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU03> brick:feeds ?vav .
  ?vav brick:feeds ?zone .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  OPTIONAL { ?sensor brick:isPointOf ?zone ; rdf:type brick:Air_Temperature_Sensor }
  OPTIONAL { ?sensor rdfs:label ?sensorLabel }
}

SELECT DISTINCT ?zone ?zoneLabel WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU03> brick:feeds ?vav .
  ?vav brick:serves ?zone .
  ?zone rdfs:label ?zoneLabel .
}

SELECT ?vav ?zone ?sensor WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU03> brick:feeds ?vav .
  ?vav brick:serves ?zone .
  ?sensor brick:isPointOf ?zone .
}

SELECT ?vav WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU03> brick:feeds ?vav .
}

SELECT ?p WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#VAV_F4_Z01> ?p <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z01> .
}

SELECT ?vav ?point ?pointLabel WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU03> brick:feeds ?vav .
  ?vav brick:hasPoint ?point .
  OPTIONAL { ?point rdfs:label ?pointLabel }
}

SELECT ?vav ?zone ?sensor WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU03> brick:feeds ?vav .
  { ?vav brick:serves ?zone } UNION { ?vav brick:feeds ?zone } .
  ?vav brick:hasPoint ?sensor .
  FILTER(CONTAINS(STR(?sensor), "Zone_Air_Temperature_Sensor"))
}

SELECT ?zone ?zoneLabel WHERE {
  VALUES ?zone { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z01> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z03> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z04> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z05> }
  ?zone rdfs:label ?zoneLabel .
}

SELECT ?sensor ?ref WHERE {
  VALUES ?sensor { <http://buildgraph.org/BG_large_office_2004_0000#VAV_F4_Z02.Zone_Air_Temperature_Sensor> <http://buildgraph.org/BG_large_office_2004_0000#VAV_F4_Z03.Zone_Air_Temperature_Sensor> <http://buildgraph.org/BG_large_office_2004_0000#VAV_F4_Z04.Zone_Air_Temperature_Sensor> }
  ?sensor ref:hasExternalReference ?ref .
}

SELECT ?vav ?sensor ?ref WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#AHU03> brick:feeds ?vav .
  ?vav brick:hasPoint ?sensor .
  FILTER(CONTAINS(STR(?sensor), "Zone_Air_Temperature_Sensor"))
  ?sensor ref:hasExternalReference ?ref .
}
